solution.exercise.c:
#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
void tree_free(tree_node*r){if(!r)return;tree_free(r->left);tree_free(r->right);free(r->value);free(r);}static tree_node*build(const char*const*p,const char*const*i,size_t n,bool*ok){if(!n)return NULL;size_t k=0;while(k<n&&strcmp(p[0],i[k]))k++;if(k==n){*ok=false;return NULL;}tree_node*r=(tree_node*)calloc(1,sizeof(tree_node));r->value=(char*)malloc(strlen(p[0])+1);strcpy(r->value,p[0]);r->left=build(p+1,i,k,ok);r->right=build(p+k+1,i+k+1,n-k-1,ok);return r;}bool tree_from_traversals(const char*const*p,const char*const*i,size_t n,tree_node**out){*out=NULL;for(size_t a=0;a<n;a++)for(size_t b=a+1;b<n;b++)if(!strcmp(p[a],p[b])||!strcmp(i[a],i[b]))return false;bool ok=true;*out=build(p,i,n,&ok);if(!ok){tree_free(*out);*out=NULL;}return ok;}

