static bool positive(int x){return x>0;}
static bool bstring(const void*p){return (*(const char*const*)p)[0]==98;}
static void string_length(const void*p,void*out){*(size_t*)out=strlen(*(const char*const*)p);}
int main(void){
const char*p[]={"a","b","d","c"},*i[]={"d","b","a","c"};tree_node*r;assert(tree_from_traversals(p,i,4,&r));assert(!strcmp(r->left->left->value,"d")&&!strcmp(r->right->value,"c"));tree_free(r);const char*q[]={"a","a"};assert(!tree_from_traversals(q,q,2,&r));const char*z[]={"z"};assert(!tree_from_traversals(p,z,1,&r));assert(tree_from_traversals(NULL,NULL,0,&r)&&!r);

return 0;}
